// Package contractsentinel: strict detection of repeated JSON object members.
package contractsentinel

import (
	"encoding/json"
	"fmt"
	"strconv"
)

// duplicateMemberError records the repeated member name and the path of the
// object containing it. The path is schema-free; duplicateMemberMessage turns
// it into a user-facing message that names the rule id or check ruleId when
// the object is a rules/checks array entry.
type duplicateMemberError struct {
	member string
	path   []jsonPathStep
}

func (e *duplicateMemberError) Error() string {
	return "duplicate JSON member " + strconv.Quote(e.member)
}

// findDuplicateJSONMember scans data structurally and returns the first JSON
// object that repeats a member name. encoding/json keeps only the last value
// for a repeated key, so without this scan an invariants object writing the
// same invariant as false then true would import just the pass, and null
// then false would smuggle a defect past the non-boolean rejection.
//
// Member names are compared after JSON string decoding: "inv" written
// literally and the same name written with a Unicode escape collide.
// Comparison is case sensitive and never trims whitespace. Every object is
// checked, including the top-level object, nested objects and every array
// element; identical member names in different objects are normal. String
// values are consumed atomically, so text inside a string that looks like
// JSON is ordinary content and is never scanned.
//
// The structural walk itself — which values are objects or arrays, how deep
// they nest and which path locates each of them — is shared with the
// character-legality check in walkJSONTokens, so the two checks can never
// drift apart on how nested input is traversed. This check only adds its own
// per-object bookkeeping of the member names already seen.
//
// Malformed JSON yields nil here; json.Unmarshal remains the single source
// of syntax errors and runs right after this scan.
func findDuplicateJSONMember(data []byte) *duplicateMemberError {
	var dup *duplicateMemberError
	// seenStack holds the member names seen so far in each open object,
	// innermost object last; enterObject and exitObject keep it in step with
	// the walk.
	var seenStack []map[string]bool
	walkJSONTokens(data, jsonWalkHooks{
		enterObject: func(path []jsonPathStep) {
			seenStack = append(seenStack, make(map[string]bool))
		},
		exitObject: func(path []jsonPathStep) {
			seenStack = seenStack[:len(seenStack)-1]
		},
		memberName: func(path []jsonPathStep, name string, start, end int) bool {
			seen := seenStack[len(seenStack)-1]
			if seen[name] {
				// path locates the containing object, not the repeated member;
				// take a copy so later walk events cannot overwrite the
				// retained path.
				dup = &duplicateMemberError{member: name, path: append([]jsonPathStep(nil), path...)}
				return true
			}
			seen[name] = true
			return false
		},
	})
	return dup
}

// duplicateMemberMessage renders the user-facing error: it states that a
// member is duplicated, quotes the decoded member name, and locates the
// object. Rules and check records are named by their id / ruleId so the user
// can tell which entry is wrong.
func duplicateMemberMessage(data []byte, dup *duplicateMemberError) string {
	return "duplicate JSON member " + strconv.Quote(dup.member) + " in " + locateDupObject(data, dup.path)
}

// locateDupObject describes the object that contains the repeated member.
func locateDupObject(data []byte, path []jsonPathStep) string {
	if len(path) == 0 {
		return "the top-level object"
	}
	head := path[0]
	switch head.key {
	case "artifact":
		if len(path) == 1 {
			return "the artifact object"
		}
		return "the artifact object (" + renderJSONPath(path[1:]) + ")"
	case "invariants":
		if len(path) == 1 {
			return "the invariants object"
		}
		return "the invariants object (" + renderJSONPath(path[1:]) + ")"
	case "rules", "checks", "findings":
		// The entry itself is the second path step (an array index).
		if len(path) >= 2 && path[1].index >= 0 {
			loc := fmt.Sprintf("%s[%d]", head.key, path[1].index) + renderJSONPath(path[2:])
			if id := arrayEntryID(data, head.key, path[1].index); id != "" {
				switch head.key {
				case "rules":
					return fmt.Sprintf("rule %q (%s)", id, loc)
				case "checks":
					return fmt.Sprintf("check record for rule %q (%s)", id, loc)
				default:
					return fmt.Sprintf("finding for rule %q (%s)", id, loc)
				}
			}
			switch head.key {
			case "rules":
				return "rule entry " + loc
			case "checks":
				return "check record " + loc
			default:
				return "finding entry " + loc
			}
		}
	}
	return "object at " + renderJSONPath(path)
}

// arrayEntryID extracts the identifying field of one rules/checks/findings
// array element. Rules carry their own id; check and finding records name the
// rule via ruleId. The unmarshal is last-key-wins for repeated members, which
// is fine here: identification only needs some id carried by the offending
// entry, and the index already makes it unambiguous.
func arrayEntryID(data []byte, field string, index int) string {
	var root map[string]any
	if err := json.Unmarshal(data, &root); err != nil {
		return ""
	}
	arr, ok := root[field].([]any)
	if !ok || index < 0 || index >= len(arr) {
		return ""
	}
	obj, ok := arr[index].(map[string]any)
	if !ok {
		return ""
	}
	idKey := "ruleId"
	if field == "rules" {
		idKey = "id"
	}
	if v, ok := obj[idKey].(string); ok {
		return v
	}
	return ""
}

// Package contractsentinel jsonchars: whole-document validation of the
// character legality of a JSON submission.
//
// encoding/json decodes two classes of illegal input without an error
// and silently rewrites the text: an invalid UTF-8 byte inside a JSON
// string, and an unpaired (or wrongly ordered) UTF-16 surrogate escape,
// are both replaced by U+FFFD. A check note carrying an isolated
// high-surrogate escape (such as \uD800) would therefore build a
// "successful" report whose evidence no longer matches the submitted
// bytes, and a source string hit by the same rewrite would change the
// content that feeds the artifact hash. The scan below re-inspects every
// raw JSON string literal -- member names and string values, at every
// depth, including members dropped later as extension data -- and rejects
// the whole submission with a precise location instead of letting any
// character be deleted or replaced.
package contractsentinel

import (
	"bytes"
	"fmt"
	"unicode/utf8"
)

const (
	// charKindEncoding classifies an invalid UTF-8 byte.
	charKindEncoding = "invalid character encoding"
	// charKindEscape classifies an unpaired or misordered surrogate escape.
	charKindEscape = "invalid Unicode escape"
)

// charEncodingError is a character-legality rejection. kind classifies it as
// an encoding or Unicode-escape problem, problem describes the exact cause,
// and offset/line/column point at the bad byte or at the backslash of the
// offending escape so the submitter can fix the original content.
type charEncodingError struct {
	kind    string
	problem string // e.g. `unpaired high surrogate escape \uD800`
	where   string // "member name", "string value" or "input"
	path    []jsonPathStep
	offset  int
	line    int
	column  int
}

func (e *charEncodingError) Error() string {
	// A whole-document encoding error carries no value path: the bad byte is
	// in whitespace or another gap outside the string literals.
	if e.where == "input" && len(e.path) == 0 {
		return fmt.Sprintf("%s: %s in JSON input (byte offset %d, line %d, column %d)",
			e.kind, e.problem, e.offset, e.line, e.column)
	}
	loc := renderCharPath(e.path)
	if e.where == "member name" && len(e.path) == 0 {
		loc = "the top-level object"
	}
	return fmt.Sprintf("%s: %s in JSON %s at %s (byte offset %d, line %d, column %d)",
		e.kind, e.problem, e.where, loc, e.offset, e.line, e.column)
}

// renderCharPath renders the location as ".key[index].key"; an empty path is
// the document root.
func renderCharPath(path []jsonPathStep) string {
	if len(path) == 0 {
		return "the top-level value"
	}
	return renderJSONPath(path)
}

// validateJSONCharacters scans data and returns the first character-legality
// violation in document order: an invalid UTF-8 byte anywhere in the document,
// or an unpaired / wrongly ordered surrogate escape inside any JSON string
// literal (member names included, at every depth and inside unknown extension
// members). It returns nil when no character problem exists; malformed JSON
// alone is left for json.Unmarshal to report, which runs right after this
// scan, mirroring findDuplicateJSONMember.
func validateJSONCharacters(data []byte) *charEncodingError {
	utf8Err := firstInvalidUTF8Byte(data)
	escapeErr := scanJSONStringEscapes(data)
	switch {
	case escapeErr != nil && (utf8Err == nil || escapeErr.offset <= utf8Err.offset):
		// On equal offsets the structural message carries the value path.
		return escapeErr
	case utf8Err != nil:
		return utf8Err
	default:
		return nil
	}
}

// firstInvalidUTF8Byte returns the first byte that is not valid UTF-8. The
// byte sweep is structural-blind, so it also covers bytes in whitespace and
// gaps that the token walk cannot reach; string-interior bytes found there
// lose the offset comparison against the path-qualified error from
// scanJSONStringEscapes.
func firstInvalidUTF8Byte(data []byte) *charEncodingError {
	for i := 0; i < len(data); {
		r, size := utf8.DecodeRune(data[i:])
		if r == utf8.RuneError && size == 1 {
			line, column := lineColumn(data, i)
			return &charEncodingError{
				kind:    charKindEncoding,
				problem: fmt.Sprintf("invalid UTF-8 byte 0x%02x", data[i]),
				where:   "input",
				offset:  i,
				line:    line,
				column:  column,
			}
		}
		i += size
	}
	return nil
}

// scanJSONStringEscapes validates every JSON string literal in the document,
// checking both raw UTF-8 validity and surrogate pairing. The structural walk
// — which values are objects or arrays, how deep they nest and which path
// locates each of them — is shared with the duplicate-member check in
// walkJSONTokens, so both checks reach exactly the same member names and
// string values at every depth, including unknown extension members; this
// check only adds the per-literal character validation. The walk is
// best-effort over syntax: a decoder error stops it quietly, because
// json.Unmarshal owns syntax errors. String tokens returned successfully have
// precise bounds even if a later part of the document is malformed.
func scanJSONStringEscapes(data []byte) *charEncodingError {
	var result *charEncodingError
	walkJSONTokens(data, jsonWalkHooks{
		memberName: func(path []jsonPathStep, name string, start, end int) bool {
			// The member name itself is a JSON string and must be legal even
			// when the member is an unknown extension that never reaches the
			// decoder. Its location is the containing object: an unpaired
			// escape in the name cannot render the name itself, so the path
			// stops at the parent.
			return recordFirst(&result, checkStringToken(data, start, end, path, true))
		},
		stringValue: func(path []jsonPathStep, start, end int) bool {
			return recordFirst(&result, checkStringToken(data, start, end, path, false))
		},
	})
	return result
}

// recordFirst stores e when it is the first violation found and reports
// whether the walk should stop.
func recordFirst(result **charEncodingError, e *charEncodingError) (stop bool) {
	if e == nil {
		return false
	}
	*result = e
	return true
}

// checkStringToken validates one raw token slice data[start:end] holding a
// JSON string token. The slice may begin with the whitespace or structural
// punctuation that separated the token from the previous one, but it always
// ends on the token's closing quote and JSON grammar permits no quote in that
// prefix, so the first quote byte is the opening quote. isMemberName selects
// how the location is described.
func checkStringToken(data []byte, start, end int, path []jsonPathStep, isMemberName bool) *charEncodingError {
	raw := data[start:end]
	q := bytes.IndexByte(raw, '"')
	if q < 0 || raw[len(raw)-1] != '"' {
		return nil // unreachable for a token returned by encoding/json
	}
	openQuote := start + q
	body := data[openQuote+1 : end-1]

	where := "string value"
	if isMemberName {
		where = "member name"
	}

	// One left-to-right pass over the literal content. Plain bytes are decoded
	// as UTF-8; backslash escapes are parsed structurally so that a backslash
	// that escapes another backslash ("\\uD800") is ordinary text, while a
	// surrogate escape must pair high-before-low with the very next escape.
	for i := 0; i < len(body); {
		abs := openQuote + 1 + i
		b := body[i]
		if b != '\\' {
			r, size := utf8.DecodeRune(body[i:])
			if r == utf8.RuneError && size == 1 {
				return charError(charKindEncoding,
					fmt.Sprintf("invalid UTF-8 byte 0x%02x", b), where, path, abs, data)
			}
			i += size
			continue
		}
		// b == '\\': an escape introduced by this backslash.
		if i+1 >= len(body) {
			return nil // malformed JSON: defer
		}
		switch body[i+1] {
		case '"', '\\', '/', 'b', 'f', 'n', 'r', 't':
			i += 2
			continue
		case 'u':
			r, ok := parseHex4(body, i)
			if !ok {
				return nil // malformed JSON: defer
			}
			switch {
			case isHighSurrogate(r):
				// The immediately following escape must be \uXXXX with a low
				// surrogate; any intervening character, a second high
				// surrogate, end of string or non-surrogate escape leaves this
				// one unpaired.
				if _, paired := pairedLowSurrogate(body, i+6); !paired {
					return charError(charKindEscape,
						fmt.Sprintf("unpaired high surrogate escape \\u%04X", r),
						where, path, abs, data)
				}
				i += 12
			case isLowSurrogate(r):
				// A low surrogate with no preceding high surrogate: this
				// includes a low-before-high ordering, whose first escape is
				// the unpaired low one.
				return charError(charKindEscape,
					fmt.Sprintf("unpaired low surrogate escape \\u%04X", r),
					where, path, abs, data)
			default:
				i += 6
			}
		default:
			return nil // malformed JSON: defer
		}
	}
	return nil
}

// parseHex4 parses the four hex digits of the "\uXXXX" escape whose backslash
// is at index i.
func parseHex4(body []byte, i int) (rune, bool) {
	if i+5 >= len(body) || body[i] != '\\' || body[i+1] != 'u' {
		return 0, false
	}
	var r rune
	for j := i + 2; j < i+6; j++ {
		c := body[j]
		var d rune
		switch {
		case c >= '0' && c <= '9':
			d = rune(c - '0')
		case c >= 'a' && c <= 'f':
			d = rune(c-'a') + 10
		case c >= 'A' && c <= 'F':
			d = rune(c-'A') + 10
		default:
			return 0, false
		}
		r = r<<4 | d
	}
	return r, true
}

// pairedLowSurrogate reports whether body[at:] begins with a "\uXXXX" escape
// denoting a low surrogate (0xDC00..0xDFFF), the only legal successor of a
// high surrogate escape. at == len(body) (end of string) is unpaired.
func pairedLowSurrogate(body []byte, at int) (rune, bool) {
	if at >= len(body) || body[at] != '\\' {
		return 0, false
	}
	r, ok := parseHex4(body, at)
	if !ok || !isLowSurrogate(r) {
		return 0, false
	}
	return r, true
}

func isHighSurrogate(r rune) bool { return 0xD800 <= r && r <= 0xDBFF }
func isLowSurrogate(r rune) bool  { return 0xDC00 <= r && r <= 0xDFFF }

// charError builds a charEncodingError, deriving line and column once.
func charError(kind, problem, where string, path []jsonPathStep, offset int, data []byte) *charEncodingError {
	line, column := lineColumn(data, offset)
	return &charEncodingError{
		kind:    kind,
		problem: problem,
		where:   where,
		path:    append([]jsonPathStep(nil), path...),
		offset:  offset,
		line:    line,
		column:  column,
	}
}

// lineColumn returns the 1-based line and rune column of byte offset off.
func lineColumn(data []byte, off int) (int, int) {
	line, lineStart := 1, 0
	for i := 0; i < off && i < len(data); i++ {
		if data[i] == '\n' {
			line++
			lineStart = i + 1
		}
	}
	return line, utf8.RuneCount(data[lineStart:off]) + 1
}

// Package contractsentinel jsonwalk: the structural walk over a JSON document
// shared by the duplicate-member check and the character-legality check.
//
// Both checks must reach exactly the same values — every object member name
// and every string value, at every depth, including content nested under
// unknown extension members — so the layer-by-layer recognition of objects
// and arrays, and the path that locates each value, is defined exactly once
// here. The checks themselves (which names repeat inside one object, which
// characters a string literal may contain) stay in their own files and plug
// into this walk as hooks.
package contractsentinel

import (
	"bytes"
	"encoding/json"
	"fmt"
	"strings"
)

// jsonPathStep locates one level of a JSON value: a member step when the
// value was reached through an object member, or an index step when it is an
// element of an array.
type jsonPathStep struct {
	key   string // member name for an object step; "" for an array step
	index int    // 0-based array index for an array step; -1 for an object step
}

// jsonWalkHooks receives the events of one structural walk over a JSON
// document. Every path slice is owned by the walk and reused for later
// events; a hook that retains a path must copy it. memberName and
// stringValue return true to stop the walk immediately, which is how a check
// reports its first problem.
type jsonWalkHooks struct {
	// enterObject fires right after an object's opening brace; path locates
	// the object itself.
	enterObject func(path []jsonPathStep)
	// exitObject fires after the matching object's closing brace.
	exitObject func(path []jsonPathStep)
	// memberName fires for every object member name. path locates the
	// containing object (not the member), name is the decoded member name,
	// and start/end bound the raw name token in the input.
	memberName func(path []jsonPathStep, name string, start, end int) (stop bool)
	// stringValue fires for every string that is a value, never a member
	// name. path locates the value and start/end bound the raw string token.
	stringValue func(path []jsonPathStep, start, end int) (stop bool)
}

// walkJSONTokens scans data structurally once, firing hooks for every object,
// member name and string value at every depth: the top-level value, nested
// objects, array elements and the contents of unknown extension members
// alike. String values are consumed atomically by the decoder, so text inside
// a string that looks like JSON is ordinary content and never produces
// events. Number literals are kept as text so an oversized exponent cannot
// abort the walk; scalar values themselves are irrelevant to both checks.
// Member names are compared after JSON string decoding, so a name written
// literally and the same name written with Unicode escapes are the same name.
//
// The walk is best-effort over syntax: a decoder error stops it quietly,
// because json.Unmarshal remains the single source of syntax errors and runs
// right after these scans.
func walkJSONTokens(data []byte, hooks jsonWalkHooks) {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	walkJSONValue(dec, nil, hooks)
}

// walkJSONValue consumes exactly one JSON value from dec, firing the hooks at
// and below it. path locates the value within its document. It reports true
// when the walk stopped, either because a hook asked to stop or because the
// input turned out to be malformed.
func walkJSONValue(dec *json.Decoder, path []jsonPathStep, hooks jsonWalkHooks) (stop bool) {
	start := int(dec.InputOffset())
	tok, err := dec.Token()
	if err != nil {
		return true // malformed JSON: defer to json.Unmarshal
	}
	end := int(dec.InputOffset())
	switch v := tok.(type) {
	case string:
		if hooks.stringValue != nil {
			return hooks.stringValue(path, start, end)
		}
		return false
	case json.Delim:
		switch v {
		case '{':
			if hooks.enterObject != nil {
				hooks.enterObject(path)
			}
			for dec.More() {
				keyStart := int(dec.InputOffset())
				keyTok, err := dec.Token()
				if err != nil {
					return true // malformed JSON: defer
				}
				keyEnd := int(dec.InputOffset())
				// Between More() and the value, Token can only be a member name.
				key, _ := keyTok.(string)
				if hooks.memberName != nil && hooks.memberName(path, key, keyStart, keyEnd) {
					return true
				}
				child := append(append([]jsonPathStep(nil), path...), jsonPathStep{key: key, index: -1})
				if walkJSONValue(dec, child, hooks) {
					return true
				}
			}
			if _, err := dec.Token(); err != nil { // consume '}'
				return true // malformed JSON: defer
			}
			if hooks.exitObject != nil {
				hooks.exitObject(path)
			}
			return false
		case '[':
			for i := 0; dec.More(); i++ {
				child := append(append([]jsonPathStep(nil), path...), jsonPathStep{index: i})
				if walkJSONValue(dec, child, hooks) {
					return true
				}
			}
			if _, err := dec.Token(); err != nil { // consume ']'
				return true // malformed JSON: defer
			}
			return false
		}
	}
	// '}' and ']' are consumed by the enclosing object or array and never
	// start a value; numbers, booleans and null are complete scalars.
	return false
}

// renderJSONPath renders schema-free path steps as ".key" and "[index]".
func renderJSONPath(path []jsonPathStep) string {
	var b strings.Builder
	for _, step := range path {
		if step.index >= 0 {
			fmt.Fprintf(&b, "[%d]", step.index)
		} else {
			b.WriteByte('.')
			b.WriteString(step.key)
		}
	}
	return b.String()
}

