1	package contractsentinel
2	
3	import (
4		"errors"
5		"strings"
6		"testing"
7	)
8	
9	// 本文件锁定 audit 提交对“JSON 对象内重复成员名”的整体拒绝：
10	// Go 的 encoding/json 对同名成员静默保留最后一个值，因此 invariants 中
11	// false 后再写 true 会只剩通过、null 后写布尔值会绕过非布尔拒绝。
12	// 这类输入没有唯一可信结论，任何一个对象出现重复成员都必须整份拒绝，
13	// 且错误要点名重复成员与所在对象（具体到哪条规则/哪条检查记录）。
14	
15	const dupRulesArtifact = `{"name":"Vault","abi":"abi","bytecode":"0x1","source":"Vault.sol"}`
16	
17	// --- 扫描器本身：在解码后的成员名上判重 ---
18	
19	func TestFindDuplicateInvariantsFalseThenTrue(t *testing.T) {
20		data := []byte(`{"invariants":{"inv":false,"inv":true}}`)
21		dup := findDuplicateJSONMember(data)
22		if dup == nil {
23			t.Fatal("false then true for the same invariant must be detected")
24		}
25		if dup.member != "inv" {
26			t.Fatalf("duplicate member = %q, want inv", dup.member)
27		}
28	}
29	
30	func TestFindDuplicateRejectsEqualValues(t *testing.T) {
31		// 重复值相同也不放行：问题在于成员出现两次，而不是值冲突。
32		data := []byte(`{"invariants":{"inv":true,"inv":true}}`)
33		if findDuplicateJSONMember(data) == nil {
34			t.Fatal("identical repeated values must still be a duplicate")
35		}
36	}
37	
38	func TestFindDuplicateNullThenBool(t *testing.T) {
39		// null 在前、布尔在后：必须在非布尔校验“看到”最后一个值之前拦下。
40		data := []byte(`{"invariants":{"inv":null,"inv":false}}`)
41		if findDuplicateJSONMember(data) == nil {
42			t.Fatal("null then bool must be detected before type validation")
43		}
44	}
45	
46	func TestFindDuplicateUnicodeEscapedName(t *testing.T) {
47		// "inv" 解码后就是 "inv"（0x69 == 'i'）：按解码后的字符串判重。
48		data := []byte(`{"invariants":{"inv":false,"inv":true}}`)
49		dup := findDuplicateJSONMember(data)
50		if dup == nil {
51			t.Fatal("literal name and the same Unicode-escaped name must collide")
52		}
53		if dup.member != "inv" {
54			t.Fatalf("duplicate member must be reported using the decoded name, got %q", dup.member)
55		}
56	}
57	
58	func TestFindDuplicateCaseSensitiveNoTrim(t *testing.T) {
59		// 名称区分大小写：Inv 与 inv 是两个成员。
60		if dup := findDuplicateJSONMember([]byte(`{"invariants":{"Inv":false,"inv":true}}`)); dup != nil {
61			t.Fatalf("Inv and inv are distinct members, got %+v", dup)
62		}
63		// 不修剪空白：" inv " 与 "inv" 是两个成员。
64		if dup := findDuplicateJSONMember([]byte(`{"invariants":{" inv ":false,"inv":true}}`)); dup != nil {
65			t.Fatalf("whitespace-padded names must not be trimmed, got %+v", dup)
66		}
67		// 反过来，完全一致的名称（仅 JSON 外围空白不同）当然算重复。
68		if dup := findDuplicateJSONMember([]byte(`{"invariants":{ "inv" : false, "inv" : true}}`)); dup == nil {
69			t.Fatal("identical names separated by whitespace must collide")
70		}
71	}
72	
73	func TestFindDuplicateEveryObjectKind(t *testing.T) {
74		cases := map[string]string{
75			"top-level":   `{"artifact":{"name":"A"},"artifact":{"name":"B"}}`,
76			"artifact":    `{"artifact":{"name":"A","name":"B"}}`,
77			"invariants":  `{"invariants":{"inv":false,"inv":true}}`,
78			"rule":        `{"rules":[{"id":"r1","version":"1","id":"r1"}]}`,
79			"check":       `{"checks":[{"ruleId":"r1","ruleId":"r1"}]}`,
80			"nested":      `{"invariants":{"inv":{"a":1,"a":2}}}`,
81			"unknown":     `{"mystery":{"a":1,"a":2}}`,
82			"top-unknown": `{"extra":1,"extra":2}`,
83		}
84		for name, input := range cases {
85			if findDuplicateJSONMember([]byte(input)) == nil {
86				t.Errorf("%s: duplicate member not detected in %s", name, input)
87			}
88		}
89	}
90	
91	func TestFindDuplicateSameNameInDifferentObjectsOK(t *testing.T) {
92		// 多条规则各自带 id、多条检查各自带 ruleId，是正常输入，不能误判。
93		input := `{
94			"artifact": {"name":"A"},
95			"rules": [
96				{"id":"r1","version":"1"},
97				{"id":"r2","version":"1"}
98			],
99			"checks": [
100				{"ruleId":"r1","status":"通过"},
101				{"ruleId":"r2","status":"通过"}
102			]
103		}`
104		if dup := findDuplicateJSONMember([]byte(input)); dup != nil {
105			t.Fatalf("equal member names in separate objects are legal: %+v", dup)
106		}
107	}
108	
109	func TestFindDuplicateIgnoresJSONLookingStrings(t *testing.T) {
110		// 源码与说明字符串里看起来再像 JSON 的文字也只是普通内容。
111		input := `{
112			"artifact": {"name":"A","source":"{\"id\":1, \"id\":2, \"id\":3}"},
113			"checks": [{"ruleId":"r1","status":"发现缺陷","note":"{\"x\":1, \"x\":2}"}]
114		}`
115		if dup := findDuplicateJSONMember([]byte(input)); dup != nil {
116			t.Fatalf("string contents must never be scanned as JSON: %+v", dup)
117		}
118	}
119	
120	func TestFindDuplicateMalformedJSONDefersToUnmarshal(t *testing.T) {
121		// 语法错误交给 json.Unmarshal 统一报错；扫描器不臆造重复。
122		for _, input := range []string{``, `{`, `{"a":1 "b":2}`, `{"a":`} {
123			if dup := findDuplicateJSONMember([]byte(input)); dup != nil {
124				t.Errorf("malformed input %q must not yield a duplicate finding, got %+v", input, dup)
125			}
126		}
127	}
128	
129	// --- ParseAuditInput：任何对象重复成员 => errInvalid，且无部分数据 ---
130	
131	func parseDupSubmission(extra string) []byte {
132		return []byte(`{
133			"artifact": ` + dupRulesArtifact + `,
134			"rules": [{"id":"r1","kind":"static","severity":"high","invariant":"inv","version":"1"}],
135			` + extra + `
136		}`)
137	}
138	
139	func expectDupRejection(t *testing.T, data []byte, wantSubstrings ...string) {
140		t.Helper()
141		artifact, rules, invariants, checks, err := ParseAuditInput(data)
142		if err == nil {
143			t.Fatalf("submission with a duplicate member must be rejected: %s", data)
144		}
145		var ei errInvalid
146		if !errors.As(err, &ei) {
147			t.Fatalf("expected errInvalid (input error), got %T: %v", err, err)
148		}
149		msg := err.Error()
150		if !strings.Contains(strings.ToLower(msg), "duplicate") {
151			t.Fatalf("error must state the member is duplicated: %v", err)
152		}
153		for _, want := range wantSubstrings {
154			if !strings.Contains(msg, want) {
155				t.Fatalf("error %q must contain %q", msg, want)
156			}
157		}
158		if artifact != (Artifact{}) || rules != nil || invariants != nil || checks != nil {
159			t.Fatalf("failure must return no partial data: %+v %+v %+v %+v", artifact, rules, invariants, checks)
160		}
161	}
162	
163	func TestParseAuditInputDuplicateInvariantFalseTrue(t *testing.T) {
164		expectDupRejection(t, parseDupSubmission(`"invariants": {"inv": false, "inv": true}`),
165			`"inv"`, "invariants object")
166	}
167	
168	func TestParseAuditInputDuplicateInvariantNullThenBool(t *testing.T) {
169		expectDupRejection(t, parseDupSubmission(`"invariants": {"inv": null, "inv": false}`),
170			`"inv"`, "invariants object")
171	}
172	
173	func TestParseAuditInputDuplicateInvariantEqualValues(t *testing.T) {
174		expectDupRejection(t, parseDupSubmission(`"invariants": {"inv": false, "inv": false}`),
175			`"inv"`)
176	}
177	
178	func TestParseAuditInputDuplicateUnicodeEscapedInvariant(t *testing.T) {
179		expectDupRejection(t, parseDupSubmission(`"invariants": {"inv": false, "inv": true}`),
180			`"inv"`)
181	}
182	
183	func TestParseAuditInputDuplicateTopLevelMember(t *testing.T) {
184		data := []byte(`{
185			"artifact": ` + dupRulesArtifact + `,
186			"rules": [{"id":"r1","version":"1"}],
187			"rules": [{"id":"r2","version":"1"}]
188		}`)
189		expectDupRejection(t, data, `"rules"`, "top-level object")
190	}
191	
192	func TestParseAuditInputDuplicateArtifactMember(t *testing.T) {
193		data := []byte(`{"artifact": {"name":"A","name":"B"},"rules":[]}`)
194		expectDupRejection(t, data, `"name"`, "artifact object")
195	}
196	
197	func TestParseAuditInputDuplicateRuleMemberNamesRule(t *testing.T) {
198		data := []byte(`{
199			"artifact": ` + dupRulesArtifact + `,
200			"rules": [
201				{"id":"rule-a","kind":"static","severity":"low","invariant":"a","version":"1"},
202				{"id":"rule-b","kind":"static","severity":"high","severity":"low","invariant":"b","version":"1"}
203			]
204		}`)
205		// 必须能区分是哪条规则：点名 rule-b 及其数组位置。
206		expectDupRejection(t, data, `"severity"`, `rule "rule-b"`, "rules[1]")
207	}
208	
209	func TestParseAuditInputDuplicateRuleIDMember(t *testing.T) {
210		// 连 id 成员本身重复也要拒绝，并给出数组位置便于定位。
211		data := []byte(`{
212			"artifact": ` + dupRulesArtifact + `,
213			"rules": [{"id":"rule-a","id":"rule-b","version":"1"}]
214		}`)
215		expectDupRejection(t, data, `"id"`, "rules[0]")
216	}
217	
218	func TestParseAuditInputDuplicateCheckMemberNamesRecord(t *testing.T) {
219		data := []byte(`{
220			"artifact": ` + dupRulesArtifact + `,
221			"rules": [
222				{"id":"rule-a","kind":"static","severity":"high","invariant":"a","version":"1"},
223				{"id":"rule-b","kind":"static","severity":"high","invariant":"b","version":"1"}
224			],
225			"checks": [
226				{"ruleId":"rule-a","version":"1","status":"通过"},
227				{"ruleId":"rule-b","version":"1","status":"发现缺陷","status":"通过","note":"x"}
228			]
229		}`)
230		// 必须能区分是哪条检查记录：点名 rule-b 及其数组位置。
231		expectDupRejection(t, data, `"status"`, "rule \"rule-b\"", "checks[1]")
232	}
233	
234	func TestParseAuditInputDuplicateUnknownMemberStillRejected(t *testing.T) {
235		// 未知字段按现有方式放行，但未知字段自身重复仍是重复成员。
236		data := []byte(`{"artifact":{"name":"A"},"rules":[],"mystery":1,"mystery":2}`)
237		expectDupRejection(t, data, `"mystery"`)
238	}
239	
